import base64,json,difflib,hashlib,re
p=json.loads(base64.b64decode(''))
before,after,tests=p['before'],p['after'],p['tests']
path='crates/heptabao-server/src/http_h2.rs'
diff=''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+path,tofile='b/'+path))
newdiff=''.join(difflib.unified_diff([],tests.splitlines(True),fromfile='/dev/null',tofile='b/crates/heptabao-server/src/http_h2_sync_worker_tests.rs'))
assert after.count(p['replacement'])==1 and after.count(p['helper'])==1
assert after.replace(p['replacement'],p['original'],1).replace(p['helper'],'',1)==before
expected_body='\n'.join('    '+line if line else line for line in p['body'].split('\n'))
assert p['replacement'].count(expected_body)==1
pat=re.compile(r'(?m)^(?:pub\(super\) )?(?:async )?fn (\w+)\(')
def funcs(s):
 m=list(pat.finditer(s));return {x.group(1):s[x.start():m[i+1].start() if i+1<len(m) else len(s)] for i,x in enumerate(m)}
a,b=funcs(before),funcs(after)
names=['negotiate','serve','request_wire','send_reply','response_frames']
checks={n:(a[n]==b[n] if n!='request_wire' else b[n].startswith(a[n])) for n in names}
assert all(checks.values()),checks
def strict_apply(original,patch):
 lines=original.splitlines(True); edits=patch.splitlines(True); out=[]; pos=0; i=2
 while i<len(edits):
  m=re.fullmatch(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@\n',edits[i]);assert m,edits[i]
  oldstart,oldcount=int(m[1]),int(m[2] or 1);newcount=int(m[4] or 1);target=oldstart-1 if oldcount else oldstart
  assert target>=pos;out.extend(lines[pos:target]);pos=target;i+=1;used=added=0
  while i<len(edits) and not edits[i].startswith('@@ '):
   row=edits[i];tag=row[0];payload=row[1:];assert tag in ' +-'
   if tag in ' -':assert pos<len(lines) and lines[pos]==payload;(pos,used)=(pos+1,used+1)
   if tag in ' +':out.append(payload);added+=1
   i+=1
  assert used==oldcount and added==newcount
 out.extend(lines[pos:]);return ''.join(out)
assert strict_apply(before,diff)==after
assert strict_apply('',newdiff)==tests
result={'status':'source_only_inverse_and_strict_diff_verified','before_bytes':len(before.encode()),'after_bytes':len(after.encode()),'new_test_bytes':len(tests.encode()),'original_body_bytes':len(p['body'].encode()),'original_body_only_indented':True,'original_dispatch_bytes':len(p['original'].encode()),'helper_exact_occurrences':1,'inverse_transformations':['replace entire new dispatch with entire original dispatch, including trailing newline and await Result punctuation','remove exactly one new helper and test module declaration block'],'inverse_whole_equal':True,'strict_apply_production_equal':True,'strict_apply_new_test_equal':True,'unchanged_original_functions':checks,'diff':diff,'new_test_diff':newdiff,'diff_sha256':hashlib.sha256(diff.encode()).hexdigest(),'new_test_diff_sha256':hashlib.sha256(newdiff.encode()).hexdigest(),'verification_harness_history':{'failed_attempts':3,'failures':['Inverse used inner-body boundary for entire dispatch.','Correction still used inner-body boundary.','Entire-dispatch inverse omitted its trailing newline.'],'source_candidate_modified':False,'product_executed':False},'rust_compile_executed':False,'product_executed':False}
print(json.dumps(result,ensure_ascii=True))
